mapper.select:
SELECT COUNT(*) FROM crm_activity
WHERE channel = 'wechat_mp'
  AND event_type = #{eventType}
AND create_time >= #{beginTime}
AND create_time <= #{endTime}

SELECT COALESCE(payload::jsonb ->> 'event_key', 'unknown') AS menuKey,
       COUNT(*) AS count
FROM crm_activity
WHERE channel = 'wechat_mp'
  AND event_type = 'channel.wechat_mp.menu.click'
AND create_time >= #{beginTime}
AND create_time <= #{endTime}

GROUP BY menuKey
ORDER BY count DESC
LIMIT #{limit}
